const getEnrolledCoursesByUser = `-- name: GetEnrolledCoursesByUser :many
WITH RECURSIVE course_nodes AS (
    SELECT n.id as course_id, n.id as node_id
    FROM nodes n
    WHERE n.node_type = 'COURSE'
    UNION ALL
    SELECT cn.course_id, child.id as node_id
    FROM nodes child
    JOIN course_nodes cn ON child.parent_id = cn.node_id
),
user_engagements AS (
    -- Completed orders
    SELECT cn.course_id, o.created_at as engaged_at
    FROM orders o
    JOIN course_nodes cn ON o.node_id = cn.node_id
    WHERE o.user_id = $1 AND o.status = 'COMPLETED'

    UNION ALL

    -- Explicit enrollments
    SELECT cn.course_id, e.enrolled_at as engaged_at
    FROM enrollments e
    JOIN course_nodes cn ON e.node_id = cn.node_id
    WHERE e.user_id = $1

    UNION ALL

    -- Progress recorded
    SELECT cn.course_id, p.updated_at as engaged_at
    FROM progress p
    JOIN course_nodes cn ON p.node_id = cn.node_id
    WHERE p.user_id = $1
),
enrolled_courses AS (
    SELECT course_id, MIN(engaged_at)::timestamptz as enrolled_at
    FROM user_engagements
    GROUP BY course_id
)
SELECT 
    n.id,
    n.parent_id,
    n.node_type,
    n.created_at,
    c.title,
    c.slug,
    c.description,
    c.thumbnail_url,
    c.is_published,
    pg.price,
    pg.currency,
    ec.enrolled_at::timestamptz as enrolled_at
FROM enrolled_courses ec
JOIN nodes n ON ec.course_id = n.id
JOIN courses c ON n.id = c.node_id
LEFT JOIN payment_gates pg ON n.id = pg.node_id
ORDER BY ec.enrolled_at DESC
`

type GetEnrolledCoursesByUserRow struct {
	ID           uuid.UUID      `json:"id"`
	ParentID     uuid.NullUUID  `json:"parent_id"`
	NodeType     NodeType       `json:"node_type"`
	CreatedAt    time.Time      `json:"created_at"`
	Title        string         `json:"title"`
	Slug         string         `json:"slug"`
	Description  sql.NullString `json:"description"`
	ThumbnailUrl sql.NullString `json:"thumbnail_url"`
	IsPublished  bool           `json:"is_published"`
	Price        sql.NullString `json:"price"`
	Currency     sql.NullString `json:"currency"`
	EnrolledAt   time.Time      `json:"enrolled_at"`
}

func (q *Queries) GetEnrolledCoursesByUser(ctx context.Context, userID uuid.UUID) ([]GetEnrolledCoursesByUserRow, error) {
	rows, err := q.db.QueryContext(ctx, getEnrolledCoursesByUser, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []GetEnrolledCoursesByUserRow
	for rows.Next() {
		var i GetEnrolledCoursesByUserRow
		if err := rows.Scan(
			&i.ID,
			&i.ParentID,
			&i.NodeType,
			&i.CreatedAt,
			&i.Title,
			&i.Slug,
			&i.Description,
			&i.ThumbnailUrl,
			&i.IsPublished,
			&i.Price,
			&i.Currency,
			&i.EnrolledAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

