const upsertPaymentGate = `-- name: UpsertPaymentGate :one
INSERT INTO payment_gates (
    node_id,
    price,
    currency
) VALUES (
    $1, $2, $3
)
ON CONFLICT (node_id) DO UPDATE
SET
    price = EXCLUDED.price,
    currency = EXCLUDED.currency
RETURNING node_id, price, currency
`

type UpsertPaymentGateParams struct {
	NodeID   uuid.UUID `json:"node_id"`
	Price    string    `json:"price"`
	Currency string    `json:"currency"`
}

// Payment Gates
func (q *Queries) UpsertPaymentGate(ctx context.Context, arg UpsertPaymentGateParams) (PaymentGate, error) {
	row := q.db.QueryRowContext(ctx, upsertPaymentGate, arg.NodeID, arg.Price, arg.Currency)
	var i PaymentGate
	err := row.Scan(&i.NodeID, &i.Price, &i.Currency)
	return i, err
}
